    " >= 0)) {\n                    return;\n                }\n                paintFrame(new Uint8Arra"
    "y(buf), from, preview);\n                if (preview) {\n                    previewRowShown = sta"
    "te.preview_row;\n                }\n            } catch (e) {\n                console.error('refre"
    "shFrame failed', e);\n            } finally {\n                frameFetchInFlight = false;\n       "
    "     }\n        }\n\n        function maybeRefreshFrame() {\n            const wasRunning = lastCapt"
    "ureState === 'running';\n            const isRunning = state.capture_state === 'running';\n       "
    "     const wasPreview = wasRunning && lastCaptureRow < 0;\n            const isPreview = isRunnin"
    "g && state.capture_row < 0;\n            const isAligned = isRunning && state.capture_row >= 0;\n\n"
    "            if (isRunning && !wasRunning) {\n                rowsPainted = 0;\n                pre"
    "viewRowShown = 0;\n            }\n            if (wasPreview && isAligned) {\n                rowsP"
    "ainted = 0;\n            }\n            lastCaptureState = state.capture_state;\n            lastCa"
    "ptureRow = state.capture_row;\n\n            let shouldFetch = false;\n            let fullReset = "
    "false;\n            let preview = false;\n            if (state.frame_serial > 0 && state.frame_se"
    "rial !== frameSerialShown) {\n                shouldFetch = true;\n                fullReset = tru"
    "e;\n            }\n            if (isAligned && state.capture_row > rowsPainted - 1) {\n           "
    "     shouldFetch = true;\n            }\n            if (isPreview && state.preview_row > previewR"
    "owShown) {\n                shouldFetch = true;\n                preview = true;\n            }\n\n  "
    "          if (shouldFetch) {\n                refreshFrame(fullReset, preview);\n            }\n   "
    "     }\n\n        function updateCaptureStatus() {\n            const status = document.getElementB"
    "yId('captureStatus');\n            if (state.capture_state === 'running') {\n                if (s"
    "tate.capture_row < 0) {\n                    if (state.preview_row > 0) {\n                       "
    " status.textContent = 'syncing… (live preview)';\n                    } else {\n                  "
    "      status.textContent = 'syncing…';\n                    }\n                } else {\n          "
    "          const pct = Math.round(state.capture_row / 240 * 100);\n                    status.text"
    "Content = `capturing… row ${state.capture_row}/240 (${pct}%)`;\n                }\n            } e"
    "lse if (state.capture_state === 'failed') {\n                status.textContent = 'Capture failed"
    "';\n            } else if ((state.capture_state === 'ok' || state.capture_state === 'idle') && st"
    "ate.frame_serial > 0) {\n                if (state.frame_serial !== frameSerialShown) {\n         "
    "           frameSerialShown = state.frame_serial;\n                    capturedTimeText = new Dat"
    "e().toLocaleTimeString();\n                }\n                status.textContent = 'Captured ' + c"
    "apturedTimeText;\n            } else {\n                status.textContent = 'Click to capture';\n "
    "           }\n        }\n\n        async function captureFrame() {\n            document.getElementB"
    "yId('error').textContent = '';\n            try {\n                if (state.project !== 33) {\n   "
    "                 await fetch('/api/select', { method: 'POST', headers: { 'Content-Type': 'applic"
    "ation/json' }, body: JSON.stringify({ project: 33 }) });\n                }\n                if (s"
    "tate.u_rst_n === false) {\n                    await fetch('/api/reset', { method: 'POST', header"
    "s: { 'Content-Type': 'application/json' }, body: JSON.stringify({ reset: false }) });\n          "
    "      }\n                const res = await fetch('/api/capture', { method: 'POST' });\n           "
    "     if (res.status === 409) {\n                    document.getElementById('captureStatus').text"
    "Content = 'Capture already in progress';\n                } else if (!res.ok) {\n                 "
    "   document.getElementById('error').textContent = `Capture failed: ${res.status}`;\n             "
    "   }\n            } catch (e) {\n                document.getElementById('error').textContent = e."
    "message;\n            }\n        }\n\n        // ---- Project 33 virtual gamepad (Pico host: state.g"
    "amepad) ----\n        const gamepadState = { start: false, up: false, down: false, left: false, r"
    "ight: false };\n\n        async function postGamepad() {\n            try {\n                const r"
    "es = await fetch('/api/gamepad', { method: 'POST', headers: { 'Content-Type': 'application/json'"
    " }, body: JSON.stringify(gamepadState) });\n                if (!res.ok) throw new Error(res.stat"
    "us);\n            } catch (e) {\n                // A failed press post is retried by the next poi"
    "nter event;\n                // never surface as red error text for a demo toy.\n                c"
    "onsole.error('gamepad post failed', e);\n            }\n        }\n\n        async function releaseA"
    "llGamepad() {\n            for (const k of Object.keys(gamepadState)) gamepadState[k] = false;\n  "
    "          await postGamepad();\n        }\n\n        function initGamepad() {\n            for (cons"
    "t btn of document.querySelectorAll('.gp-btn')) {\n                const key = btn.dataset.gp;\n   "
    "             const press = (e) => {\n                    e.preventDefault();\n                    "
    "if (!gamepadState[key]) {\n                        gamepadState[key] = true;\n                    "
    "    postGamepad();\n                    }\n                };\n                const release = (e) "
    "=> {\n                    if (e) e.preventDefault();\n                    if (gamepadState[key]) {"
    "\n                        gamepadState[key] = false;\n                        postGamepad();\n     "
    "               }\n                };\n                btn.addEventListener('pointerdown', press);\n"
    "                btn.addEventListener('pointerup', release);\n                btn.addEventListener"
    "('pointerleave', release);\n                btn.addEventListener('pointercancel', release);\n     "
    "       }\n            document.addEventListener('visibilitychange', () => {\n                if (d"
    "ocument.hidden) releaseAllGamepad();\n            });\n        }\n\n        function setCaptureClock"
    "(hz) {\n            api('/api/capture_clock', { hz: parseInt(hz, 10) });\n        }\n\n        async"
    " function api(path, body) {\n            document.getElementById('error').textContent = '';\n     "
    "       try {\n                const opts = body ? {\n                    method: 'POST',\n         "
    "           headers: { 'Content-Type': 'application/json' },\n                    body: JSON.strin"
    "gify(body)\n                } : {};\n                const res = await fetch(path, opts);\n        "
    "        if (!res.ok) {\n                    const text = await res.text();\n                    th"
    "row new Error(`${res.status}: ${text}`);\n                }\n                state = { ...state, ."
    "..await res.json() };\n                updateUi();\n            } catch (e) {\n                docu"
    "ment.getElementById('error').textContent = e.message;\n            }\n        }\n\n        function "
    "updateOutputWidgets() {\n            if (!currentDescriptor || !currentDescriptor.outputs) return"
    ";\n\n            for (const output of currentDescriptor.outputs) {\n                if (output.type"
    " === 'leds') {\n                    for (const bit of output.bits) {\n                        cons"
    "t on = (state.uo_out >> bit) & 1;\n                        const el = document.getElementById(`ou"
    "t_led_${bit}`);\n                        if (el) el.classList.toggle('on', on);\n                 "
    "   }\n                } else if (output.type === 'seven_seg') {\n                    const segs = "
    "output.segments;\n                    const segState = {};\n                    for (const [name, "
    "src] of Object.entries(segs)) {\n                        const [bus, idxStr] = src.split('.');\n  "
    "                      const idx = parseInt(idxStr, 10);\n                        const value = bu"
    "s === 'uio' ? state.uio_value : state.uo_out;\n                        segState[name] = (value >>"
    " idx) & 1;\n                    }\n                    const inverted = ((state.ui_in >> 4) & 1) !"
    "== 0;\n                    for (let i = 0; i < output.digits.length; i++) {\n                     "
    "   const selectSrc = output.digits[i].select;\n                        const [bus, idxStr] = sele"
    "ctSrc.split('.');\n                        const idx = parseInt(idxStr, 10);\n                    "
    "    const value = bus === 'uio' ? state.uio_value : state.uo_out;\n                        const "
    "selected = (value >> idx) & 1;\n                        const cvs = document.getElementById(`seve"
    "n_seg_digit_${i}`);\n                        if (cvs) {\n                            drawSevenSeg("
    "cvs, selected ? segState : {}, inverted);\n                        }\n                    }\n      "
    "          }\n            }\n        }\n\n        function updateUi() {\n            const select = do"
    "cument.getElementById('projectSelect');\n            if (select.value !== String(state.project)) "
    "{\n                select.value = state.project;\n                loadDescriptor(state.project);\n "
    "           }\n            document.getElementById('projectStatus').textContent = `Current: ${stat"
    "e.project}`;\n\n            if (!editingFreq) {\n                document.getElementById('freqValue"
    "').textContent = state.clock_freq_hz.toLocaleString();\n            }\n            document.getEle"
    "mentById('runBtn').textContent = state.clock_running ? 'Stop' : 'Run';\n            document.getE"
    "lementById('clockStatus').textContent = state.clock_running ? 'Running' : 'Stopped';\n\n          "
    "  // Pico-only project 33 extras: degrade to hidden when the host\n            // doesn't report "
    "them (ESP32 build).\n            const is33 = state.project === 33;\n            const rateRow = d"
    "ocument.getElementById('captureRateRow');\n            const rateSel = document.getElementById('c"
    "aptureRate');\n            const showRate = is33 && state.capture_hz !== undefined;\n            r"
    "ateRow.style.display = showRate ? 'flex' : 'none';\n            if (showRate && document.activeEl"
    "ement !== rateSel && rateSel.value !== String(state.capture_hz)) {\n                rateSel.value"
    " = String(state.capture_hz);\n            }\n            document.getElementById('gamepadPanel').s"
    "tyle.display =\n                is33 && state.gamepad ? 'block' : 'none';\n\n            updateOutp"
    "utWidgets();\n            maybeRefreshFrame();\n            updateCaptureStatus();\n        }\n\n    "
    "    function selectProject(project) {\n            api('/api/select', { project });\n        }\n\n  "
    "      function setClock(freq) {\n            api('/api/clock', { running: true, freq_hz: freq });"
    "\n        }\n\n        function toggleClock() {\n            api('/api/clock', { running: !state.clo"
    "ck_running, freq_hz: state.clock_freq_hz || 1000 });\n        }\n\n        function stepClock() {\n "
    "           api('/api/step', {});\n        }\n\n        function editFreq() {\n            if (editin"
    "gFreq) return;\n            editingFreq = true;\n            const span = document.getElementById("
    "'freqValue');\n            const current = state.clock_freq_hz || 1000;\n            span.innerHTM"
    "L = `<input type=\"number\" id=\"freqInput\" value=\"${current}\" min=\"10\" max=\"25000000\">`;\n         "
    "   const input = document.getElementById('freqInput');\n            input.focus();\n            in"
    "put.select();\n            input.addEventListener('keydown', (e) => {\n                if (e.key ="
    "== 'Enter') saveFreq();\n                if (e.key === 'Escape') { editingFreq = false; updateUi("
    "); }\n            });\n            input.addEventListener('blur', saveFreq);\n        }\n\n        fu"
    "nction saveFreq() {\n            if (!editingFreq) return;\n            const input = document.get"
    "ElementById('freqInput');\n            const freq = parseInt(input.value, 10);\n            editin"
    "gFreq = false;\n            if (!isNaN(freq) && freq > 0) {\n                api('/api/clock', { r"
    "unning: true, freq_hz: freq });\n            } else {\n                updateUi();\n            }\n "
    "       }\n\n        loadProjects();\n        initGamepad();\n        api('/api/state');\n        setI"
    "nterval(() => api('/api/state'), 250);\n    </script>\n</body>\n</html>\n";
